using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
internal static class QuestCaptureAcceptance {
 static IEnumerable<T> Find<T>(DependencyObject root) where T:DependencyObject{if(root==null)yield break;if(root is T)yield return (T)root;foreach(var x in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var y in Find<T>(x))yield return y;}
 internal static void Ui(Window owner,string folder,string sample){var store=new Store(Path.Combine(folder,"qi-ui"));var c=new DofusCharacter{id="capture-ui",name="Personnage fictif",guide="parcours-exemple",classCode="Sacri"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;store.Save();TougliReader.Cache(store,c.guide,sample);Exception failure=null;QuestCaptureUi.Show(owner,store,()=>{},Brushes.White,Brushes.LightGray,Brushes.Black,w=>{try{Find<TextBox>(w).Single(x=>x.Name=="CaptureNames").Text="Première quête fictive\nNom inconnu du catalogue";Action<string> click=t=>Find<Button>(w).First(b=>Equals(b.Content,t)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));click("Analyser les noms");var validate=Find<Button>(w).First(b=>Equals(b.Content,"Valider l’import pour ce personnage"));if(validate.IsEnabled)throw new Exception("Import sans confirmation");click("○ Je confirme que les quêtes sélectionnées sont terminées");if(!validate.IsEnabled)throw new Exception("Confirmation sans effet");validate.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var saved=new Store(store.Root);if(saved.Value.dofus.capturedQuests.Count!=1||DofusCompanion.Find(saved.Value,saved.Value.dofus.characters[0]).done.Count!=2)throw new Exception("Import UI non persisté ou note cochée");}catch(Exception e){failure=e;}finally{w.Close();}});if(failure!=null)throw failure;File.WriteAllText(Path.Combine(folder,"QUEST_IMPORT_UI_PASS.txt"),"PASS: real analysis, confirmation gate, selected exact match only, unknown line ignored, duplicate quest steps and persisted state.");}
 internal static int RunOcr(string folder){try{Ocr(folder);return 0;}catch(Exception e){Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"QUEST_IMPORT_OCR_FAIL.txt"),e.ToString());return 1;}}
 internal static void Ocr(string folder){Directory.CreateDirectory(folder);var file=Path.Combine(folder,"synthetic-quest.png");using(var bitmap=new System.Drawing.Bitmap(900,220))using(var g=System.Drawing.Graphics.FromImage(bitmap))using(var font=new System.Drawing.Font("Arial",26)){g.Clear(System.Drawing.Color.FromArgb(30,30,30));g.DrawString("Quêtes terminées",font,System.Drawing.Brushes.White,20,20);g.DrawString("Première quête fictive",font,System.Drawing.Brushes.White,20,100);bitmap.Save(file,System.Drawing.Imaging.ImageFormat.Png);}string text=System.Threading.Tasks.Task.Run(()=>QuestCaptureOcr.Read(file,System.Threading.CancellationToken.None)).GetAwaiter().GetResult();if(!text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Any(t=>QuestCaptureImport.Key(t)==QuestCaptureImport.Key("Première quête fictive")))throw new Exception("OCR capture synthétique non reconnu : "+text);File.WriteAllText(Path.Combine(folder,"QUEST_IMPORT_OCR_PASS.txt"),"PASS: local Windows French OCR on synthetic image; real game capture not provided for validation.");}
}
